        throw new Error(`colorBg="${s.colorBg}", ожидалось #0a2540`);
      }
    });

    await test('Цвет фона #052e16 (тёмно-зелёный)', async () => {
      await ctrl({ colorBg: '#052e16' });
      await sleep(700);
      const s = await vState();
